// TH14 synthetic training aliases (subset); see transcribe/th14/bullet-types.md.
// Native type 8 (rice) maps to catalog slot 480; color passed separately.
const TH14_RICE: int = 480;

// TH14 v1.00b Stage 3 mid-stage wave: MainSub02 first loop, 8x GirlB01.
// Source: st03.ecl.txt:563-583 (entry), GirlB01 149-159, GirlB01_at 161-177,
// GirlB01_at2 179-226 (dependency). Source frame 0 = card frame OPENING_BUFFER.
const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

// GirlB01_at2 fire origin: spd 1.5/1.7/1.9/2.1/2.3, etSprite(0,8,6).
const BULLET_COLOR: int = 6;
// moveVelTime target angles in exact BAM: 1.3744467rad=78.75deg, 0.19634955rad=11.25deg.
const GIRL_TURN1: int = 14336;
const GIRL_TURN2: int = 2048;

// GirlB01_at2 (source 179-226): 5-bullet aimed rice bursts.
async sub girl_at2() {
    var rank: int = global(GVAR_RANK);
    var volleys: int = 32;            // diffI($B,1,32,32,32)
    var gap: int = 30;                // !H
    if rank == RANK_EASY {
        volleys = 1;                  // !E
        gap = 180;                    // !E 180
    } else if rank == RANK_NORMAL {
        gap = 60;                     // !N 60
    } else if rank == RANK_LUNATIC {
        gap = 20;                     // !LO 20 (Lunatic)
    }
    for v in 0..volleys {
        // etAim(0,0)+etCount(0,1,1): base angle to player plus one jitter, no spread.
        for k in 0..5 {               // $C=4 -> 5 shots
            var spd: fx = 1.5fx + 0.2fx * (k as fx);        // %A, step 0.2
            var dir: angle = aim_player() + ((rand(1024) - 512) as angle);  // %RANDRAD/64, +-pi/64
            // etExSet(0,0,0,2,1,...): ANIM a=1 keeps position -= 4*velocity.
            var bx: fx = $self_x - 4fx * spd * cos(dir);
            var by: fx = $self_y - 4fx * spd * sin(dir);
            _ = fire(TH14_RICE, BULLET_COLOR, bx, by, spd, dir, none, none);
            wait(1);
        }
        wait(gap);
    }
}

// GirlB01_at (source 161-177). mirror=1 is enmCreateM's initial child mirror:
// 404/405 are the mirrored variants, so the own x motion is reflected.
async sub girl(mirror: int) {
    set_invuln(65535);
    set_hurtbox(12fx);                // setHurtbox(24,24) -> r=12
    set_hitbox(8fx);                  // setHitbox(16,16) -> r=8
    var turn1: angle = GIRL_TURN1 as angle;
    var turn2: angle = GIRL_TURN2 as angle;
    if mirror != 0 {
        turn1 = (32768 - GIRL_TURN1) as angle;
        turn2 = (32768 - GIRL_TURN2) as angle;
    }
    move_vel(0, 90deg, 3fx, EASE_LINEAR);        // moveVel(pi/2, 3)
    move_vel(60, turn1, 0fx, EASE_QUAD_IN);      // moveVelTime(60,1,78.75deg,0)
    wait(60);
    spawn girl_at2();                            // @GirlB01_at2() async
    wait(120);
    move_vel(60, turn2, 1fx, EASE_LINEAR);       // moveVelTime(60,0,11.25deg,1)
    loop { wait(1000); }
}

// MainSub02 (source 563-583): two passes of 4 creations at 30/80/130/180 and
// 210/260/310/360; %A starts at -128 and advances 32 per creation.
async sub pattern() {
    wait(OPENING_BUFFER);
    var x: fx = -128fx;
    var b: int = 2;                   // $B = 2
    while b != 0 {                    // if ($B--) goto MainSub02_140
        b = b - 1;
        wait(30);
        _ = spawn_enemy(x, -32fx, 200, 0, 1000, 0, girl(0));   // enmCreate
        x = x + 32fx;
        wait(50);
        _ = spawn_enemy(x, -32fx, 200, 0, 1000, 0, girl(1));   // enmCreateM
        x = x + 32fx;
        wait(50);
        _ = spawn_enemy(x, -32fx, 200, 0, 1000, 0, girl(0));
        x = x + 32fx;
        wait(50);
        _ = spawn_enemy(x, -32fx, 200, 0, 1000, 0, girl(1));
        x = x + 32fx;
    }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
